def compute(vars):
    company_return = vars["v1"]
    index_return = vars["v2"]
    difference = company_return - index_return

    return {
        "value": difference,
        "trace": {
            "company_return": company_return,
            "index_return": index_return,
            "difference": difference,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "index value"
            }
        }
    }
